window.__PIONEER_REGISTER_TEST("TEST_HIST_SET_14", [
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'करनाल का युद्ध (1739 ई.)' का ऐतिहासिक संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था।\n2. फिरोजशाह तुगलक ने लूट के माल (खुम्स) का राज्य हिस्सा 4/5 से घटाकर शरीयत के अनुसार 1/5 कर दिया तथा सैनिकों व इक्ता पदों को वंशानुगत बना दिया।\n3. मुगल प्रशासन में 'मीर बख्शी' साम्राज्य का मुख्य सेनापति (कमांडर-इन-चीफ) होता था और सम्राट के बिना भी युद्ध की घोषणा कर सकता था।\n4. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चंदावर का युद्ध (1194 ई.)' का ऐतिहासिक संबंध 'दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (फिरोजशाह तुगलक ने लूट के माल (खुम्स) का राज्य हिस्सा 4/5 से घटाकर शरीयत के अनुसार 1/5 कर दिया तथा सैनिकों व इक्ता पदों को वंशानुगत बना दिया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. नक्शबंदी सिलसिला सबसे कट्टरवादी सूफी धारा थी जिसके संत शेख अहमद सरहिन्दी ('मुजद्दिद अलिफ सानी') ने अकबर की उदार नीति व 'वहदत-उल-वुजूद' का विरोध कर 'वहदत-उल-शुहूद' दिया।\n2. दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।\n3. कुतुबुद्दीन ऐबक ने दिल्ली को अपनी स्थायी राजधानी बनाया और बगदाद के खलीफा से सुल्तान की औपचारिक उपाधि व सनद प्राप्त की।\n4. चोल शासक परांतक प्रथम के उत्तरमेरूर अभिलेख (कांचीपुरम) में ग्राम 'सभा' की समितियों के लिए लॉटरी (कुडवोलाई) चुनाव और कठोर योग्यताओं का विस्तृत वर्णन है।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: ऐबक ने लाहौर से शासन किया और कभी सुल्तान की उपाधि व खलीफा से मान्यता नहीं ली; दिल्ली राजधानी और खलीफा मान्यता इल्तुतमिश ने प्राप्त की।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. चंदावर का युद्ध (1194 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n2. पानीपत का तृतीय युद्ध (1761 ई.) : अहमद शाह अब्दाली ने सदाशिवराव भाऊ के नेतृत्व वाली मराठा सेना को हराया\n3. खानवा का युद्ध (1527 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":2,"explanation":"युग्म 1 सही (1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।) युग्म 2 सही (पानीपत के तृतीय युद्ध में अफगान शासक अहमद शाह अब्दाली ने मराठों को निर्णायक रूप से हराया।) युग्म 3 सही (16 मार्च 1527 को खानवा के युद्ध में बाबर ने राणा सांगा के नेतृत्व वाले राजपूत संघ को परास्त किया।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गयासुद्दीन तुगलक मकबरा   B. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)\nC. गुरु तेग बहादुर (नौवें गुरु)   D. सासाराम झील मकबरा\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["गुरु तेग बहादुर (नौवें गुरु)","गयासुद्दीन तुगलक मकबरा","सासाराम झील मकबरा","ऐबक एवं (वंश)"],"correct":3,"explanation":"कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), गयासुद्दीन तुगलक मकबरा (1325 ई.), सासाराम झील मकबरा (1545 ई.), गुरु तेग बहादुर (नौवें गुरु) (1675 ई.)। अतः सर्वप्रथम कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-खैरात' का ऐतिहासिक संबंध 'शाही पत्राचार, फरमान व अभिलेख विभाग' से था।\nकथन-2: सिख गुरु परंपरा के अंतर्गत 'गुरु रामदास (चौथे गुरु)' का ऐतिहासिक संबंध 'आदि ग्रंथ का संकलन (1604) एवं हरमंदिर साहिब निर्माण' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'दीवान-ए-खैरात' का सही संबंध 'असहायों व गरीब कन्याओं की सहायता का दान विभाग (फिरोज तुगलक)' से था — फिरोजशाह तुगलक ने गरीब व असहाय नागरिकों की मदद हेतु 'दीवान-ए-खैरात' बनाया। (2) 'गुरु रामदास (चौथे गुरु)' का सही संबंध 'अमृतसर नगर एवं संतोखसर सरोवर की स्थापना (1577)' से था — अकबर द्वारा प्रदत्त 500 बीघा भूमि पर गुरु रामदास ने अमृतसर नगर बसाया।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n2. चौसा का युद्ध (1539 ई.) : शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\n3. खानवा का युद्ध (1527 ई.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":1,"explanation":"युग्म 1 सही (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।) युग्म 2 सही (1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।) युग्म 3 गलत (सही: खानवा का युद्ध (1527 ई.) — बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. सुहरावर्दी सिलसिला (भारत)   2. अटाला मस्जिद (जौनपुर)\n3. अब्दुर रज्जाक (फारस/समरकंद)   4. अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण","options":["सुहरावर्दी सिलसिला (भारत) → अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → अटाला मस्जिद (जौनपुर) → अब्दुर रज्जाक (फारस/समरकंद)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → अटाला मस्जिद (जौनपुर) → सुहरावर्दी सिलसिला (भारत) → अब्दुर रज्जाक (फारस/समरकंद)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → सुहरावर्दी सिलसिला (भारत) → अब्दुर रज्जाक (फारस/समरकंद) → अटाला मस्जिद (जौनपुर)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → सुहरावर्दी सिलसिला (भारत) → अटाला मस्जिद (जौनपुर) → अब्दुर रज्जाक (फारस/समरकंद)"],"correct":3,"explanation":"सही कालानुक्रम: अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण (1025 ई.), सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), अटाला मस्जिद (जौनपुर) (1408 ई.), अब्दुर रज्जाक (फारस/समरकंद) (1443 ई.)"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा   B. पुरंदर की संधि (1665 ई.)\nC. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   D. सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["एवं गयासुद्दीन (लौह व )","गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा","पुरंदर की संधि (1665 ई.)","सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)"],"correct":0,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा (1320-1325 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.), सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) (1699 ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"ऐतिहासिक संदर्भ में 'ऐबक (लाखबख्श, लाहौर राजधानी, कुतुब मीनार नींव व अढ़ाई दिन का झोपड़ा); इल्तुतमिश (वास्तविक संस्थापक, दिल्ली राजधानी, चालीसा दल, इक्ता, टंका-जीतल)' (प्रमुख कार्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ","रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)","ुद्दीन ऐबक एवं (मामलूक"],"correct":3,"explanation":"ऐबक की मृत्यु 1210 ई. में लाहौर में चौगान (पोलो) खेलते समय घोड़े से गिरकर हुई। उसने सूफी संत ख्वाजा कुतुबुद्दीन बख्तियार काकी की स्मृति में कुतुब मीनार शुरू कराई। [गुलाम वंश)]"},
  {"q":"ऐतिहासिक संदर्भ में '1. दोआब में कर वृद्धि; 2. राजधानी परिवर्तन (दिल्ली से देवगिरि/दौलताबाद, 1327); 3. सांकेतिक मुद्रा (काँसा/ताँबा, 1329-30); 4. खुरासान अभियान; 5. कराचिल अभियान' (प्रमुख योजनाएँ) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)","रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार"],"correct":2,"explanation":"1351 ई. में थट्टा (सिन्ध) में मृत्यु पर इतिहासकार बदायूँनी ने लिखा—'सुल्तान को प्रजा से और प्रजा को सुल्तान से मुक्ति मिल गई।' इसी काल में विजयनगर (1336) व बहमनी (1347) बने।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: इब्नबतूता (मोरक्को यात्री, 1333 ई. भारत आगमन) ने अपनी अरबी पुस्तक 'रेहला' में मुहम्मद बिन तुगलक के दरबार, डाक प्रणाली ('उलुक' व 'दावा'), पान व नारियल का सजीव चित्रण किया।\nकथन-2: बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) इब्नबतूता (मोरक्को यात्री, 1333 ई. भारत आगमन) ने अपनी अरबी पुस्तक 'रेहला' में मुहम्मद बिन तुगलक के दरबार, डाक प्रणाली ('उलुक' व 'दावा'), पान व नारियल का सजीव चित्रण किया। (2) बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'किताब-ए-नवरस' का ऐतिहासिक संबंध 'अल-बरूनी' से था।\n2. दक्कनी सल्तनत व राजवंश के अंतर्गत 'बरार (इमादशाही) व बीदर (बरीदशाही)' का ऐतिहासिक संबंध 'युसुफ आदिल शाह' से था।\n3. मराठा अष्टप्रधान परिषद के अंतर्गत 'सुमंत (दबीर)' का ऐतिहासिक संबंध 'वित्त एवं राजस्व लेखा-जोखा मंत्री' से था।\n4. 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. तराइन का प्रथम युद्ध (1191 ई.)   |   1. चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\nB. करनाल का युद्ध (1739 ई.)   |   2. शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\nC. चौसा का युद्ध (1539 ई.)   |   3. पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\nD. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष)   |   4. नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया","options":["A-3, B-4, C-2, D-1","A-3, B-2, C-4, D-1","A-4, B-3, C-2, D-1","A-3, B-4, C-1, D-2"],"correct":0,"explanation":"सही सुमेलन: तराइन का प्रथम युद्ध (1191 ई.) (पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया), करनाल का युद्ध (1739 ई.) (नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया), चौसा का युद्ध (1539 ई.) (शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की), नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) (चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. विदेशी यात्री एवं शासक के अंतर्गत 'इब्नबतूता (मोरक्को)' का ऐतिहासिक संबंध 'जहाँगीर (1615-1619 ई.)' से था।\n2. दीवान-ए-विजारत आय-व्यय, कर निर्धारण व सभी विभागों के वित्तीय निरीक्षण का केंद्र था।\n3. नूरजहाँ ने अपने पिता मिर्जा गियास बेग की स्मृति में यमुना तट पर एत्मादुद्दौला का मकबरा बनवाया।\n4. चिश्तियों के विपरीत शेख बहाउद्दीन जकरिया ने सुल्तान इल्तुतमिश से 'शेख-उल-इस्लाम' पद व धन स्वीकार किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'इब्नबतूता (मोरक्को)' का सही संबंध 'मुहम्मद बिन तुगलक (1333 ई.)' से था — मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।"},
  {"q":"ऐतिहासिक संदर्भ में 'स्थायी नकद-वेतन सेना, 'दाग' (घोड़े दागना) व 'हुलिया/चेहरा'; बाजार नियंत्रण (शहना-ए-मंडी, दीवान-ए-रियासत, सरा-ए-अदल); भूमि की पैमाइश 'बिस्वा' (1/20 बीघा)' (प्रमुख सुधार) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)","अलाउद्दीन खिलजी: व सैन्य-राजस्व","रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)","मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ"],"correct":1,"explanation":"अलाउद्दीन ने अलाई दरवाजा (प्रथम वैज्ञानिक गुंबद व घोड़े की नाल वाला मेहराब), सीरी किला, हजार सितून व हौज-ए-अलाई का निर्माण कराया; अमीर खुसरो उसके दरबारी थे।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. इब्नबतूता (मोरक्को यात्री, 1333 ई. भारत आगमन) ने अपनी अरबी पुस्तक 'रेहला' में मुहम्मद बिन तुगलक के दरबार, डाक प्रणाली ('उलुक' व 'दावा'), पान व नारियल का सजीव चित्रण किया।\n2. बैरम खाँ के पुत्र रहीम ने नीति दोहे व बरवै रचे तथा रसखान ने कृष्ण भक्ति के सवैये लिखे।\n3. गयासुद्दीन बलबन ने 'तुर्कान-ए-चहलगानी' (चालीसा गुट) का गठन कर तुर्क अमीरों को असीमित प्रशासनिक शक्तियाँ प्रदान कीं।\n4. टोडरमल की दहसाला व्यवस्था में भूमि 4 वर्गों में थी: पोलज (प्रतिवर्ष खेती), परती, चाचर (3-4 वर्ष खाली), बंजर।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: बलबन स्वयं चालीसा का सदस्य था, किंतु सुल्तान बनने पर उसने राजतंत्र की रक्षा हेतु चालीसा दल को पूर्णतः नष्ट कर दिया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'सामूगढ़ का युद्ध (1658 ई.)' का ऐतिहासिक संबंध 'नादिर शाह बनाम मुगल बादशाह मुहम्मद शाह 'रंगीला'' से था।\nकथन-2: अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('सामूगढ़ का युद्ध (1658 ई.)' का सही संबंध 'औरंगजेब व मुराद बनाम दारा शिकोह' से था — मई 1658 में आगरा के निकट सामूगढ़ युद्ध में औरंगजेब की जीत से शाहजहाँ कैद व उत्तराधिकार तय हुआ।)। कथन-2 सत्य है (अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. फर्नओ नूनिज (पुर्तगाल)   2. मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल)\n3. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)   4. चौसा का युद्ध (1539 ई.)","options":["मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) → फर्नओ नूनिज (पुर्तगाल) → कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) → चौसा का युद्ध (1539 ई.)","कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) → मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) → फर्नओ नूनिज (पुर्तगाल) → चौसा का युद्ध (1539 ई.)","मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) → कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) → चौसा का युद्ध (1539 ई.) → फर्नओ नूनिज (पुर्तगाल)","मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) → कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) → फर्नओ नूनिज (पुर्तगाल) → चौसा का युद्ध (1539 ई.)"],"correct":3,"explanation":"सही कालानुक्रम: मिहिर भोज (गुर्जर-प्रतिहार), गोपाल व धर्मपाल (पाल) (836-885 ई.), कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), फर्नओ नूनिज (पुर्तगाल) (1535 ई.), चौसा का युद्ध (1539 ई.) (1539 ई.)"},
  {"q":"'फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ' के ऐतिहासिक संदर्भ में 'कर सुधार व धर्मांधता' निम्नलिखित में से क्या है?","options":["24 कष्टदायक कर समाप्त कर केवल 4 शरिया कर (खराज, खुम्स, जजिया, जकात); ब्राह्मणों पर भी जजिया लागू; अशोक के टोपरा-मेरठ स्तंभ दिल्ली लाया","'वेट्टी' (बेगार/श्रम कर) व 'कदमाई' (भू-राजस्व); 'वेल्लनवगई', 'ब्रह्मदेय', 'शालाभोग' (विद्यालय हेतु भूमि), 'देवदान', 'पल्लीचंदम' (जैन संस्थान)","खराज 50% (मसाहत के आधार पर), घरी (गृहकर) व चरी (चरागाह कर); मलिक काफूर के नेतृत्व में देवगिरि, वारंगल, द्वारसमुद्र व मदुरै अभियान","ज्ञानदेव ('ज्ञानेश्वरी'), नामदेव (अभंग व गुरु ग्रंथ साहिब में पद), एकनाथ, तुकाराम (शिवाजी समकालीन) व रामदास ('दासबोध', धरकरी)"],"correct":0,"explanation":"फिरोज ने हिसार, फिरोजाबाद, फतेहाबाद, जौनपुर व फिरोजपुर नगर बसाए और अपनी आत्मकथा 'फुतुहात-ए-फिरोजशाही' लिखी।"},
  {"q":"[UPSC/PCS सूची सुमेलन — विदेशी यात्री एवं शासक] सूची-I को सूची-II से सुमेलित कीजिए:\nA. इब्नबतूता (मोरक्को)   |   1. देवराय द्वितीय (विजयनगर, 1443 ई.)\nB. अब्दुर रज्जाक (फारस/समरकंद)   |   2. देवराय प्रथम (विजयनगर, 1420 ई.)\nC. फर्नओ नूनिज (पुर्तगाल)   |   3. मुहम्मद बिन तुगलक (1333 ई.)\nD. निकोलो कोंटी (इटली)   |   4. अच्युतदेवराय (विजयनगर, ~1535 ई.)","options":["A-3, B-1, C-2, D-4","A-3, B-1, C-4, D-2","A-1, B-3, C-4, D-2","A-3, B-4, C-1, D-2"],"correct":1,"explanation":"सही सुमेलन: इब्नबतूता (मोरक्को) (मुहम्मद बिन तुगलक (1333 ई.)), अब्दुर रज्जाक (फारस/समरकंद) (देवराय द्वितीय (विजयनगर, 1443 ई.)), फर्नओ नूनिज (पुर्तगाल) (अच्युतदेवराय (विजयनगर, ~1535 ई.)), निकोलो कोंटी (इटली) (देवराय प्रथम (विजयनगर, 1420 ई.))।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. विदेशी यात्री एवं शासक के अंतर्गत 'निकोलो कोंटी (इटली)' का ऐतिहासिक संबंध 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से था।\n2. मुगलकालीन प्रमुख युद्ध के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था।\n3. विदेशी यात्री एवं शासक के अंतर्गत 'फ्रांस्वा बर्नियर एवं टैवर्नियर' का ऐतिहासिक संबंध 'देवराय प्रथम (विजयनगर, 1420 ई.)' से था।\n4. मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. भक्ति मत एवं प्रवर्तक के अंतर्गत 'अद्वैतवाद' का ऐतिहासिक संबंध 'रामानुजाचार्य (11वीं सदी, श्रीरंगम)' से था।\n2. विदेशी यात्री एवं शासक के अंतर्गत 'डोमिंगो पायस (पुर्तगाल)' का ऐतिहासिक संबंध 'अच्युतदेवराय (विजयनगर, ~1535 ई.)' से था।\n3. फारसी राजदूत अब्दुर रज्जाक तुगलक शासक फिरोजशाह के दरबार में दिल्ली आया था और उसने बहमनी की बजाय दिल्ली की सती प्रथा पर लिखा।\n4. सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: भक्ति मत एवं प्रवर्तक के अंतर्गत 'शुद्धाद्वैतवाद एवं पुष्टिमार्ग' का ऐतिहासिक संबंध 'बसवन्ना (बसव)' से था।\nकथन-2: डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('शुद्धाद्वैतवाद एवं पुष्टिमार्ग' का सही संबंध 'वल्लभाचार्य' से था — वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।)। कथन-2 सत्य है (डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'तराइन का प्रथम युद्ध (1191 ई.)' का ऐतिहासिक संबंध 'मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया' से था।\n2. गयासुद्दीन तुगलक (गाजी मलिक) दिल्ली सल्तनत का पहला सुल्तान था जिसने सिंचाई हेतु नहरों का निर्माण कराया और अलाउद्दीन की कठोर मसाहत प्रणाली के स्थान पर नरम नस्क/बंटाई कर लागू किया।\n3. बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।\n4. इब्नबतूता (मोरक्को यात्री, 1333 ई. भारत आगमन) ने अपनी अरबी पुस्तक 'रेहला' में मुहम्मद बिन तुगलक के दरबार, डाक प्रणाली ('उलुक' व 'दावा'), पान व नारियल का सजीव चित्रण किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'तराइन का प्रथम युद्ध (1191 ई.)' का सही संबंध 'पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया' से था — 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. तक्कोलम का युद्ध (949 ई.)   2. अफनासी निकितिन (रूस)\n3. गुरु रामदास (चौथे गुरु)   4. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","options":["तक्कोलम का युद्ध (949 ई.) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → अफनासी निकितिन (रूस) → गुरु रामदास (चौथे गुरु)","अफनासी निकितिन (रूस) → तक्कोलम का युद्ध (949 ई.) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → गुरु रामदास (चौथे गुरु)","तक्कोलम का युद्ध (949 ई.) → अफनासी निकितिन (रूस) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → गुरु रामदास (चौथे गुरु)","तक्कोलम का युद्ध (949 ई.) → अफनासी निकितिन (रूस) → गुरु रामदास (चौथे गुरु) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":2,"explanation":"सही कालानुक्रम: तक्कोलम का युद्ध (949 ई.) (949 ई.), अफनासी निकितिन (रूस) (1470 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), गुरु रामदास (चौथे गुरु) (1577 ई.)"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सामूगढ़ का युद्ध (1658 ई.)   B. किताब-उल-हिन्द\nC. मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध   D. पानीपत का तृतीय युद्ध (1761 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["सामूगढ़ का युद्ध (1658 ई.)","मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध","उल-हिन्द","पानीपत का तृतीय युद्ध (1761 ई.)"],"correct":2,"explanation":"किताब-उल-हिन्द (11वीं सदी ई.), मुहम्मद गोरी: तराइन का प्रथम, द्वितीय व चंदावर युद्ध (1192 ई.), सामूगढ़ का युद्ध (1658 ई.) (1658 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)। अतः सर्वप्रथम किताब-उल-हिन्द।"},
  {"q":"[PSC/CDS युग्म पहचान — विदेशी यात्री एवं शासक] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. निकोलो कोंटी (इटली) : देवराय द्वितीय (विजयनगर, 1443 ई.)\n2. अब्दुर रज्जाक (फारस/समरकंद) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n3. अफनासी निकितिन (रूस) : अच्युतदेवराय (विजयनगर, ~1535 ई.)\n4. इब्नबतूता (मोरक्को) : मुहम्मद बिन तुगलक (1333 ई.)","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा। (अन्य सही युग्म: निकोलो कोंटी (इटली)→देवराय प्रथम (विजयनगर, 1420 ई.), अब्दुर रज्जाक (फारस/समरकंद)→देवराय द्वितीय (विजयनगर, 1443 ई.), अफनासी निकितिन (रूस)→बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.))।"},
  {"q":"'सल्तनत कालीन शब्दावली: फवाजिल, सोंधर, हक्क-ए-शर्ब व खालिसा' के ऐतिहासिक संदर्भ में 'सैन्य व कर तथ्य' निम्नलिखित में से क्या है?","options":["'मसाहत' (भूमि पैमाइश), 'इतलाक' (नकद वेतन के बदले राजस्व आदेश पत्र — फिरोज तुगलक)","खराज 50% (मसाहत के आधार पर), घरी (गृहकर) व चरी (चरागाह कर); मलिक काफूर के नेतृत्व में देवगिरि, वारंगल, द्वारसमुद्र व मदुरै अभियान","24 कष्टदायक कर समाप्त कर केवल 4 शरिया कर (खराज, खुम्स, जजिया, जकात); ब्राह्मणों पर भी जजिया लागू; अशोक के टोपरा-मेरठ स्तंभ दिल्ली लाया","'वेट्टी' (बेगार/श्रम कर) व 'कदमाई' (भू-राजस्व); 'वेल्लनवगई', 'ब्रह्मदेय', 'शालाभोग' (विद्यालय हेतु भूमि), 'देवदान', 'पल्लीचंदम' (जैन संस्थान)"],"correct":0,"explanation":"'बरीद' (गुप्तचर) और 'मुन्हियान' (अलाउद्दीन के गुप्त सूचक) बाजार व प्रांतीय अधिकारियों पर सुल्तान की सीधी नजर रखते थे।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'चंदावर का युद्ध (1194 ई.)' का ऐतिहासिक संबंध 'दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया' से था।\n2. अल-बरूनी ने 11वीं सदी में भारत की विद्या, धर्म, विज्ञान व समाज पर 'किताब-उल-हिन्द' लिखी।\n3. बरनी ने बलबन से फिरोजशाह तुगलक के प्रारंभिक काल तक का राजनीतिक इतिहास व राजत्व सिद्धांत लिखा।\n4. कल्चुरी राजा बिज्जल के मंत्री बसवन्ना ने जातिभेद व वैदिक कर्मकांड के विरुद्ध वीरशैव परंपरा शुरू की।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'चंदावर का युद्ध (1194 ई.)' का सही संबंध 'मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया' से था — 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. शिवाजी के अष्टप्रधान मंत्रिमंडल के सभी आठ पदों को 1674 में ही वंशानुगत कर दिया गया और पंडितराव को भी युद्धों का नेतृत्व अनिवार्य था।\n2. विदेशी यात्री एवं शासक के अंतर्गत 'इब्नबतूता (मोरक्को)' का ऐतिहासिक संबंध 'जहाँगीर (1615-1619 ई.)' से था।\n3. विदेशी यात्री एवं शासक के अंतर्गत 'निकोलो कोंटी (इटली)' का ऐतिहासिक संबंध 'देवराय द्वितीय (विजयनगर, 1443 ई.)' से था।\n4. बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सद्र-उस-सुदूर की संस्तुति पर विद्वानों व फकीरों को जीवनयापन हेतु दी गई राजस्व-मुक्त भूमि मदद-ए-माअश थी।\nकथन-2: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'खानवा युद्ध (1527 ई.)' का ऐतिहासिक संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (सद्र-उस-सुदूर की संस्तुति पर विद्वानों व फकीरों को जीवनयापन हेतु दी गई राजस्व-मुक्त भूमि मदद-ए-माअश थी।)। कथन-2 गलत है — 'खानवा युद्ध (1527 ई.)' का सही संबंध 'बाबर बनाम राणा सांगा (मेवाड़)' से था — 17 मार्च 1527 को खानवा में बाबर ने जिहाद का नारा देकर राणा सांगा के राजपूत संघ को हराया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम   B. गुरु अमरदास (तीसरे गुरु)\nC. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   D. सासाराम झील मकबरा\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम","एवं (लौह व )","सासाराम झील मकबरा","गुरु अमरदास (तीसरे गुरु)"],"correct":1,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम (1336 ई.), सासाराम झील मकबरा (1545 ई.), गुरु अमरदास (तीसरे गुरु) (1552-1574 ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।\nकथन-2: वाकियानवीस दरबारी घटनाक्रम दर्ज करने व गुप्तचर सूचनाओं को संकलित करने का कार्य करते थे।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया। (2) वाकियानवीस दरबारी घटनाक्रम दर्ज करने व गुप्तचर सूचनाओं को संकलित करने का कार्य करते थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा।\nकथन-2: फिरोजशाह तुगलक ने अपने पूर्ववर्ती सुल्तानों की परंपरा के विपरीत सल्तनत में दास प्रथा को पूर्णतः अवैध घोषित कर समाप्त कर दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (शेरशाह सूरी ने मुगल अकबर के प्रशासनिक ढाँचे का अग्रदूत बनकर चाँदी का मानक 'रुपया' चलाया, जो ब्रिटिश काल तक भारतीय मुद्रा का आधार बना रहा।)। कथन-2 गलत है — फिरोज तुगलक दासों का अत्यंत शौकीन था—उसके पास लगभग 1,80,000 दास थे जिनके प्रबंधन के लिए उसने 'दीवान-ए-बंदगान' विभाग बनाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: फिरोजशाह तुगलक ने अपने पूर्ववर्ती सुल्तानों की परंपरा के विपरीत सल्तनत में दास प्रथा को पूर्णतः अवैध घोषित कर समाप्त कर दिया।\nकथन-2: इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (फिरोज तुगलक दासों का अत्यंत शौकीन था—उसके पास लगभग 1,80,000 दास थे जिनके प्रबंधन के लिए उसने 'दीवान-ए-बंदगान' विभाग बनाया।)। कथन-2 सत्य है (इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. तबकात-ए-नासिरी   2. जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा\n3. विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम   4. चौसा का युद्ध (1539 ई.)","options":["तबकात-ए-नासिरी → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा → चौसा का युद्ध (1539 ई.)","तबकात-ए-नासिरी → चौसा का युद्ध (1539 ई.) → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","तबकात-ए-नासिरी → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → चौसा का युद्ध (1539 ई.) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → तबकात-ए-नासिरी → चौसा का युद्ध (1539 ई.) → जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा"],"correct":2,"explanation":"सही कालानुक्रम: तबकात-ए-नासिरी (1260 ई.), विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम (1336 ई.), चौसा का युद्ध (1539 ई.) (1539 ई.), जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा (1605-1627 ई.)"},
  {"q":"ऐतिहासिक संदर्भ में 'रजिया (1236-40 — दिल्ली की प्रथम मुस्लिम महिला शासिका, कुलाह-कबा पहनी); बलबन (चहलगानी का दमन, राजत्व का दैवीय सिद्धांत, सिजदा-पैबोस, नौरोज उत्सव)' (प्रमुख राजनीतिक कार्य) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ","कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार","सुल्तान एवं गयासुद्दीन (लौह व रक्त नीति)"],"correct":3,"explanation":"रजिया के विरुद्ध विद्रोह में अल्तूनिया (भटिंडा) व तुर्क अमीरों (याकूत प्रसंग) की भूमिका रही; 1240 ई. में कैथल के निकट उसकी हत्या हुई।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. सामूगढ़ का युद्ध (1658 ई.)   B. करनाल का युद्ध (1739 ई.)\nC. मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ   D. सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","बिन","करनाल का युद्ध (1739 ई.)","सामूगढ़ का युद्ध (1658 ई.)"],"correct":1,"explanation":"मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ (1325-1351 ई.), सामूगढ़ का युद्ध (1658 ई.) (1658 ई.), सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) (1699 ई.), करनाल का युद्ध (1739 ई.) (1739 ई.)। अतः सर्वप्रथम मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. किताब-ए-नवरस   B. फ्रांस्वा बर्नियर एवं टैवर्नियर\nC. किताब-उल-हिन्द   D. वीरशैव (लिंगायत) आंदोलन\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["फ्रांस्वा बर्नियर एवं टैवर्नियर","वीरशैव (लिंगायत) आंदोलन","किताब-उल","किताब-ए-नवरस"],"correct":2,"explanation":"किताब-उल-हिन्द (11वीं सदी ई.), वीरशैव (लिंगायत) आंदोलन (12वीं सदी ई.), किताब-ए-नवरस (1600 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सर्वप्रथम किताब-उल-हिन्द।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   B. हुमायूँनामा\nC. पानीपत का द्वितीय युद्ध (1556 ई.)   D. अटाला मस्जिद (जौनपुर)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अटाला मस्जिद (जौनपुर)","हुमायूँनामा","पानीपत का द्वितीय युद्ध (1556 ई.)","एवं (लौह व )"],"correct":3,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), अटाला मस्जिद (जौनपुर) (1408 ई.), पानीपत का द्वितीय युद्ध (1556 ई.) (1556 ई.), हुमायूँनामा (16वीं सदी ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ   B. गयासुद्दीन तुगलक मकबरा\nC. तराइन का प्रथम युद्ध (1191 ई.)   D. विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम\nइनमें से कौन-सी घटना **सबसे अंत में (सबसे बाद में)** घटित हुई?","options":["गयासुद्दीन तुगलक मकबरा","तुगलक की एवं","विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम","तराइन का प्रथम युद्ध (1191 ई.)"],"correct":1,"explanation":"तराइन का प्रथम युद्ध (1191 ई.) (1191 ई.), गयासुद्दीन तुगलक मकबरा (1325 ई.), विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम (1336 ई.), फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ (1351-1388 ई.)। अतः सबसे अंत में फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'रहीम दोहावली / प्रेमवाटिका' का ऐतिहासिक संबंध 'मोतमिद खाँ' से था।\nकथन-2: मिर्जा मुहम्मद ने औरंगजेब के काल में भारतीय संगीत, छंद व रागों के परिचय हेतु यह फारसी ग्रंथ लिखा।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('रहीम दोहावली / प्रेमवाटिका' का सही संबंध 'अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य)' से था — बैरम खाँ के पुत्र रहीम ने नीति दोहे व बरवै रचे तथा रसखान ने कृष्ण भक्ति के सवैये लिखे।)। कथन-2 सत्य है (मिर्जा मुहम्मद ने औरंगजेब के काल में भारतीय संगीत, छंद व रागों के परिचय हेतु यह फारसी ग्रंथ लिखा।)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. सिख गुरु परंपरा के अंतर्गत 'गुरु तेग बहादुर (नौवें गुरु)' का ऐतिहासिक संबंध 'गुरुमुखी लिपि का विकास व लंगर प्रथा का स्थायीकरण' से था।\n2. दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।\n3. सल्तनत विभाग एवं सुल्तान के अंतर्गत 'दीवान-ए-अर्ज' का ऐतिहासिक संबंध 'बकाया राजस्व वसूली व भ्रष्ट अधिकारियों की जाँच (अलाउद्दीन)' से था।\n4. कृष्णदेवराय के दरबार के प्रसिद्ध 'अष्टदिग्गज' संस्कृत के आठ वैदिक कर्मकांडी मंत्रियों की प्रशासनिक परिषद थी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: फिरोजशाह तुगलक ने अपने पूर्ववर्ती सुल्तानों की परंपरा के विपरीत सल्तनत में दास प्रथा को पूर्णतः अवैध घोषित कर समाप्त कर दिया।\nकथन-2: मुगल दरबार में अब्दुल्ला खाँ और हुसैन अली (सैय्यद बंधु) इतने शक्तिशाली हो गए थे कि उन्होंने चार सम्राट (फर्रुखसियर, रफी-उद-दरजात, रफी-उद-दौला, मुहम्मद शाह) गद्दी पर बैठाए।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (फिरोज तुगलक दासों का अत्यंत शौकीन था—उसके पास लगभग 1,80,000 दास थे जिनके प्रबंधन के लिए उसने 'दीवान-ए-बंदगान' विभाग बनाया।)। कथन-2 सत्य है (मुगल दरबार में अब्दुल्ला खाँ और हुसैन अली (सैय्यद बंधु) इतने शक्तिशाली हो गए थे कि उन्होंने चार सम्राट (फर्रुखसियर, रफी-उद-दरजात, रफी-उद-दौला, मुहम्मद शाह) गद्दी पर बैठाए।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा   B. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)\nC. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान   D. पुरंदर की संधि (1665 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["ऐबक एवं (वंश)","छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा","पुरंदर की संधि (1665 ई.)"],"correct":0,"explanation":"कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा (1320-1325 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.)। अतः सर्वप्रथम कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया।\nकथन-2: बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) टीपू सुल्तान ने श्रीरंगपट्टनम में फ्रांस के सम्मान में 'स्वतंत्रता का वृक्ष' लगाया, स्वयं को 'नागरिक टीपू' कहा और आधुनिक नौसेना बोर्ड व रेशम उत्पादन को बढ़ावा दिया। (2) बलबन ने सुल्तान को पृथ्वी पर ईश्वर का प्रतिनिधि ('नियाबत-ए-खुदाई') व 'जिल्ल-ए-इलाही' घोषित कर ईरानी दरबारी शिष्टाचार 'सिजदा व पैबोस' लागू किया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: गयासुद्दीन बलबन ने 'तुर्कान-ए-चहलगानी' (चालीसा गुट) का गठन कर तुर्क अमीरों को असीमित प्रशासनिक शक्तियाँ प्रदान कीं।\nकथन-2: 1674 ई. में रायगढ़ किले में काशी के पंडित विश्वेश्वर (गंगाभट्ट) ने शिवाजी का राज्याभिषेक किया और उन्होंने 'छत्रपति', 'हैंदव धर्मोद्धारक' व 'गोब्राह्मण प्रतिपालक' उपाधि ली।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (बलबन स्वयं चालीसा का सदस्य था, किंतु सुल्तान बनने पर उसने राजतंत्र की रक्षा हेतु चालीसा दल को पूर्णतः नष्ट कर दिया।)। कथन-2 सत्य है (1674 ई. में रायगढ़ किले में काशी के पंडित विश्वेश्वर (गंगाभट्ट) ने शिवाजी का राज्याभिषेक किया और उन्होंने 'छत्रपति', 'हैंदव धर्मोद्धारक' व 'गोब्राह्मण प्रतिपालक' उपाधि ली।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।\nकथन-2: सिख गुरु परंपरा के अंतर्गत 'गुरु अमरदास (तीसरे गुरु)' का ऐतिहासिक संबंध 'अमृतसर नगर एवं संतोखसर सरोवर की स्थापना (1577)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।)। कथन-2 गलत है — 'गुरु अमरदास (तीसरे गुरु)' का सही संबंध '22 गद्दियाँ (मंजी प्रथा) व 'आनंद कारज' विवाह गीत रचना' से था — गुरु अमरदास ने सती व पर्दा प्रथा का विरोध किया तथा सम्राट अकबर से गोइंदवाल में भेंट की।"},
  {"q":"'अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार' के ऐतिहासिक संदर्भ में 'कर व दक्षिण विजय' निम्नलिखित में से क्या है?","options":["ज्ञानदेव ('ज्ञानेश्वरी'), नामदेव (अभंग व गुरु ग्रंथ साहिब में पद), एकनाथ, तुकाराम (शिवाजी समकालीन) व रामदास ('दासबोध', धरकरी)","'वेट्टी' (बेगार/श्रम कर) व 'कदमाई' (भू-); 'वेल्लनवगई', 'ब्रह्मदेय', 'शालाभोग' (विद्यालय हेतु भूमि), 'देवदान', 'पल्लीचंदम' (जैन संस्थान)","24 कष्टदायक कर समाप्त कर केवल 4 शरिया कर (खराज, खुम्स, जजिया, जकात); ब्राह्मणों पर भी जजिया लागू; अशोक के टोपरा-मेरठ स्तंभ दिल्ली लाया","खराज 50% (मसाहत के आधार पर), घरी (गृहकर) व चरी (चरागाह कर); मलिक काफूर के नेतृत्व में देवगिरि, वारंगल, द्वारसमुद्र व मदुरै अभियान"],"correct":3,"explanation":"अलाउद्दीन ने अलाई दरवाजा (प्रथम वैज्ञानिक गुंबद व घोड़े की नाल वाला मेहराब), सीरी किला, हजार सितून व हौज-ए-अलाई का निर्माण कराया; अमीर खुसरो उसके दरबारी थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।\nकथन-2: गुरु अमरदास ने सती व पर्दा प्रथा का विरोध किया तथा सम्राट अकबर से गोइंदवाल में भेंट की।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया। (2) गुरु अमरदास ने सती व पर्दा प्रथा का विरोध किया तथा सम्राट अकबर से गोइंदवाल में भेंट की।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. सल्तनत काल में 'तकावी' (सोंधर) शब्द युद्ध में पराजित हिंदू राजाओं से लिए जाने वाले दंडात्मक हर्जाने के लिए प्रयुक्त होता था।\n2. चोल शासक परांतक प्रथम के उत्तरमेरूर अभिलेख (कांचीपुरम) में ग्राम 'सभा' की समितियों के लिए लॉटरी (कुडवोलाई) चुनाव और कठोर योग्यताओं का विस्तृत वर्णन है।\n3. अमीर खुसरो (1253-1325 ई., पटियाली में जन्म) निजामुद्दीन औलिया के प्रिय शिष्य थे जिन्होंने हिंदवी व फारसी संस्कृति के समन्वय ('गंगा-जमुनी तहजीब') की नींव रखी।\n4. 1565 के तालीकोटा युद्ध में बीजापुर, गोलकुंडा, अहमदनगर व बीदर की संयुक्त सेना ने विजयनगर साम्राज्य को ध्वस्त किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":0,"explanation":"कथन 1 असत्य है। सुधार: 'सोंधर' या 'तकावी' अकाल व सूखे के समय किसानों को बीज, बैल व कुओं के लिए राज्य द्वारा दिया जाने वाला अग्रिम कृषि ऋण था (मुहम्मद बिन तुगलक ने प्रमुखता से दिया)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: मध्यकालीन ग्रंथ एवं लेखक के अंतर्गत 'रहीम दोहावली / प्रेमवाटिका' का ऐतिहासिक संबंध 'मोतमिद खाँ' से था।\nकथन-2: अकबर की मनसबदारी व्यवस्था वंशानुगत नहीं थी—मनसबदार की मृत्यु के बाद उसकी संपत्ति राजकोष ('जब्त') कर ली जाती थी ('एस्कीट' प्रणाली), हालांकि बाद में संतानों को नया मनसब मिल सकता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है ('रहीम दोहावली / प्रेमवाटिका' का सही संबंध 'अब्दुर्रहीम खानखाना एवं रसखान (हिंदी-ब्रज काव्य)' से था — बैरम खाँ के पुत्र रहीम ने नीति दोहे व बरवै रचे तथा रसखान ने कृष्ण भक्ति के सवैये लिखे।)। कथन-2 सत्य है (अकबर की मनसबदारी व्यवस्था वंशानुगत नहीं थी—मनसबदार की मृत्यु के बाद उसकी संपत्ति राजकोष ('जब्त') कर ली जाती थी ('एस्कीट' प्रणाली), हालांकि बाद में संतानों को नया मनसब मिल सकता था।)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. पुरंदर की संधि (1665 ई.)   B. किताब-ए-नवरस\nC. तराइन का प्रथम युद्ध (1191 ई.)   D. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["किताब-ए-नवरस","पुरंदर की संधि (1665 ई.)","छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","(ई.)"],"correct":3,"explanation":"तराइन का प्रथम युद्ध (1191 ई.) (1191 ई.), किताब-ए-नवरस (1600 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.)। अतः सर्वप्रथम तराइन का प्रथम युद्ध (1191 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।\nकथन-2: सल्तनत काल में 'तकावी' (सोंधर) शब्द युद्ध में पराजित हिंदू राजाओं से लिए जाने वाले दंडात्मक हर्जाने के लिए प्रयुक्त होता था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।)। कथन-2 गलत है — 'सोंधर' या 'तकावी' अकाल व सूखे के समय किसानों को बीज, बैल व कुओं के लिए राज्य द्वारा दिया जाने वाला अग्रिम कृषि ऋण था (मुहम्मद बिन तुगलक ने प्रमुखता से दिया)।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद   2. एकशरण संप्रदाय (असम)\n3. विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम   4. सुहरावर्दी सिलसिला (भारत)","options":["सुहरावर्दी सिलसिला (भारत) → एकशरण संप्रदाय (असम) → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद","विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → सुहरावर्दी सिलसिला (भारत) → एकशरण संप्रदाय (असम) → 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद","सुहरावर्दी सिलसिला (भारत) → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → एकशरण संप्रदाय (असम) → 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद","सुहरावर्दी सिलसिला (भारत) → विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम → 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद → एकशरण संप्रदाय (असम)"],"correct":2,"explanation":"सही कालानुक्रम: सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), विजयनगर साम्राज्य की स्थापना एवं राजवंश क्रम (1336 ई.), एकशरण संप्रदाय (असम) (15वीं-16वीं सदी), 18वीं सदी के स्वायत्त क्षेत्रीय राज्य: बंगाल, अवध व हैदराबाद (1724 ई.)"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. इब्नबतूता (मोरक्को)   B. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान\nC. फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ   D. किताब-ए-नवरस\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","किताब-ए-नवरस","फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ","इब्नबतूता"],"correct":3,"explanation":"इब्नबतूता (मोरक्को) (1333 ई.), फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ (1351-1388 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), किताब-ए-नवरस (1600 ई.)। अतः सर्वप्रथम इब्नबतूता (मोरक्को)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तराइन का प्रथम युद्ध (1191 ई.) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\n2. हाइडेस्पीज का युद्ध (326 ई.पू.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n3. पानीपत का द्वितीय युद्ध (1556 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":3,"explanation":"युग्म 1 गलत (सही: तराइन का प्रथम युद्ध (1191 ई.) — पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया)। युग्म 2 गलत (सही: हाइडेस्पीज का युद्ध (326 ई.पू.) — सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की)। युग्म 3 गलत (सही: पानीपत का द्वितीय युद्ध (1556 ई.) — अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।\nकथन-2: 1565 के तालीकोटा युद्ध में बीजापुर, गोलकुंडा, अहमदनगर व बीदर की संयुक्त सेना ने विजयनगर साम्राज्य को ध्वस्त किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया। (2) 1565 के तालीकोटा युद्ध में बीजापुर, गोलकुंडा, अहमदनगर व बीदर की संयुक्त सेना ने विजयनगर साम्राज्य को ध्वस्त किया।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. गुरु अर्जुन देव (पाँचवें गुरु)   2. सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)\n3. अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री   4. अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण","options":["अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री → गुरु अर्जुन देव (पाँचवें गुरु) → सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री → अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → गुरु अर्जुन देव (पाँचवें गुरु) → सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → गुरु अर्जुन देव (पाँचवें गुरु) → अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री → सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री → सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) → गुरु अर्जुन देव (पाँचवें गुरु)"],"correct":0,"explanation":"सही कालानुक्रम: अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण (1025 ई.), अमर-नायक प्रणाली व विजयनगर आए विदेशी यात्री (1565 ई.), गुरु अर्जुन देव (पाँचवें गुरु) (1604 ई.), सिखों के दस गुरु एवं खालसा पंथ की स्थापना (1699) (1699 ई.)"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. संगोला की संधि (1750 ई.)   B. मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ\nC. जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा   D. सिकंदर लोदी का मकबरा (1517)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["संगोला की संधि (1750 ई.)","जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा","बिन","सिकंदर लोदी का मकबरा (1517)"],"correct":2,"explanation":"मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ (1325-1351 ई.), सिकंदर लोदी का मकबरा (1517) (1517 ई.), जहाँगीर (सलीम): न्याय की जंजीर, चित्रकला का स्वर्ण युग व नूरजहाँ जुंटा (1605-1627 ई.), संगोला की संधि (1750 ई.) (1750 ई.)। अतः सर्वप्रथम मुहम्मद बिन तुगलक की पांच महत्वाकांक्षी योजनाएँ।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   B. तालीकोटा का युद्ध (1565 ई.)\nC. गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा   D. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["तालीकोटा का युद्ध (1565 ई.)","रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)","गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा","ऐबक एवं (वंश)"],"correct":3,"explanation":"कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), गयासुद्दीन तुगलक एवं मंगोल आक्रमणों से रक्षा (1320-1325 ई.), तालीकोटा का युद्ध (1565 ई.) (1565 ई.)। अतः सर्वप्रथम कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. तालीकोटा का युद्ध (1565 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\n2. पानीपत का द्वितीय युद्ध (1556 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n3. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n4. चंदावर का युद्ध (1194 ई.) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":2,"explanation":"केवल युग्म 3 सही है: 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया। (अन्य सही युग्म: तालीकोटा का युद्ध (1565 ई.)→दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया, पानीपत का द्वितीय युद्ध (1556 ई.)→अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया, चंदावर का युद्ध (1194 ई.)→मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया)।"},
  {"q":"[PSC/CDS युग्म पहचान — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित चार युग्मों में से कौन-सा **एक** युग्म सही सुमेलित है?\n1. खानवा का युद्ध (1527 ई.) : सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की\n2. हाइडेस्पीज का युद्ध (326 ई.पू.) : दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया\n3. तालीकोटा का युद्ध (1565 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया\n4. चंदावर का युद्ध (1194 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया","options":["केवल युग्म 1","केवल युग्म 2","केवल युग्म 3","केवल युग्म 4"],"correct":3,"explanation":"केवल युग्म 4 सही है: 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया। (अन्य सही युग्म: खानवा का युद्ध (1527 ई.)→बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली, हाइडेस्पीज का युद्ध (326 ई.पू.)→सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की, तालीकोटा का युद्ध (1565 ई.)→दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।\nकथन-2: सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने। (2) सल्तनत के सबसे विद्वान सुल्तान मुहम्मद बिन तुगलक ने योग्यता के आधार पर पद दिए, होली जैसे हिंदू त्योहारों में भाग लिया और जैन विद्वान जिनप्रभ सूरी का सम्मान किया।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. गुरु अंगद देव (दूसरे गुरु)   2. चंदावर का युद्ध (1194 ई.)\n3. अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण   4. पानीपत का तृतीय युद्ध (1761 ई.)","options":["अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → चंदावर का युद्ध (1194 ई.) → गुरु अंगद देव (दूसरे गुरु) → पानीपत का तृतीय युद्ध (1761 ई.)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → चंदावर का युद्ध (1194 ई.) → पानीपत का तृतीय युद्ध (1761 ई.) → गुरु अंगद देव (दूसरे गुरु)","चंदावर का युद्ध (1194 ई.) → अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → गुरु अंगद देव (दूसरे गुरु) → पानीपत का तृतीय युद्ध (1761 ई.)","अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण → गुरु अंगद देव (दूसरे गुरु) → चंदावर का युद्ध (1194 ई.) → पानीपत का तृतीय युद्ध (1761 ई.)"],"correct":0,"explanation":"सही कालानुक्रम: अरब (मुहम्मद बिन कासिम) एवं महमूद गजनवी के आक्रमण (1025 ई.), चंदावर का युद्ध (1194 ई.) (1194 ई.), गुरु अंगद देव (दूसरे गुरु) (1539-1552 ई.), पानीपत का तृतीय युद्ध (1761 ई.) (1761 ई.)"},
  {"q":"मोरक्को निवासी यात्री इब्नबतूता किस दिल्ली सुल्तान के दरबार में पहुँचा था?","options":["देवराय प्रथम (विजयनगर, 1420 ई.)","मुहम्मद बिन तुगलक (1333 ई.)","कृष्णदेवराय (विजयनगर, ~1520 ई.)","देवराय द्वितीय (विजयनगर, 1443 ई.)"],"correct":1,"explanation":"मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा। उनके यात्रा-वृत्तांत 'रेहला' में डाक प्रथा (उलुक-दावा) व सल्तनत समाज का सजीव विवरण है।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: तंजौर के प्रसिद्ध बृहदेश्वर (राजराजेश्वर) मंदिर का निर्माण पल्लव शासक महेंद्रवर्मन द्वारा ईंटों से कराया गया था।\nकथन-2: अलाउद्दीन खिलजी ने दक्षिण भारत के राज्यों (देवगिरि, वारंगल, होयसल) को प्रत्यक्ष रूप से दिल्ली सल्तनत के प्रांतों में मिला लिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) बृहदेश्वर मंदिर (तंजौर) का निर्माण चोल शासक राजराज प्रथम ने लगभग 1010 ई. में ग्रेनाइट पत्थर से द्रविड़ शैली के शिखर रूप में कराया था। (2) अलाउद्दीन ने व्यावहारिक नीति अपनाते हुए दक्षिण भारतीय राज्यों को केवल करद (वार्षिक नजराना देने वाले अधीनस्थ राज्य) बनाया, प्रत्यक्ष विलय नहीं किया।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. ऐतिहासिक युद्ध एवं परिणाम के अंतर्गत 'तराइन का प्रथम युद्ध (1191 ई.)' का ऐतिहासिक संबंध 'मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया' से था।\n2. गयासुद्दीन तुगलक ने खिज्र खाँ को हराकर भारत में लोदी वंश की नींव डाली और सल्तनत में नहरों का निर्माण पूर्णतः बंद करा दिया।\n3. गयासुद्दीन बलबन ने 'तुर्कान-ए-चहलगानी' (चालीसा गुट) का गठन कर तुर्क अमीरों को असीमित प्रशासनिक शक्तियाँ प्रदान कीं।\n4. अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (अलाउद्दीन खिलजी प्रथम सुल्तान था जिसने भूमि की वास्तविक माप (मसाहत) कराकर उपज का 50% भू-राजस्व तय किया तथा बिचौलियों (खुत, मुकद्दम, चौधरी) के विशेषाधिकार छीने।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — विदेशी यात्री एवं शासक] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. इब्नबतूता (मोरक्को) : बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)\n2. डोमिंगो पायस (पुर्तगाल) : कृष्णदेवराय (विजयनगर, ~1520 ई.)\n3. फ्रांस्वा बर्नियर एवं टैवर्नियर : शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)\n4. अब्दुर रज्जाक (फारस/समरकंद) : देवराय द्वितीय (विजयनगर, 1443 ई.)","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":0,"explanation":"युग्म 1 गलत है: 'इब्नबतूता (मोरक्को)' का सही संबंध 'मुहम्मद बिन तुगलक (1333 ई.)' से है (न कि 'बहमनी सल्तनत (मुहम्मद शाह III काल, ~1470 ई.)' से)। मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा।"},
  {"q":"ऐतिहासिक संदर्भ में '5 बड़ी नहरें व 'हक्क-ए-शर्ब' (10% सिंचाई कर); 'दीवान-ए-खैरात' (दान), 'दीवान-ए-बंदगान' (1.8 लाख दास), 'दार-उल-शफा' (मुफ्त अस्पताल) व रोजगार दफ्तर' (प्रमुख विभाग व नहरें) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)","फिरोजशाह तुगलक की कल्याणकारी एवं कट्टर नीतियाँ","अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार","कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)"],"correct":1,"explanation":"फिरोज ने हिसार, फिरोजाबाद, फतेहाबाद, जौनपुर व फिरोजपुर नगर बसाए और अपनी आत्मकथा 'फुतुहात-ए-फिरोजशाही' लिखी।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. आलू, तंबाकू और मक्का ऋग्वैदिक काल से ही भारत की प्राचीनतम मुख्य फसलें थीं जिनका वर्णन चरक संहिता में विस्तार से है।\n2. औरंगजेब ने हिंदू अधिकारियों की संख्या शून्य कर दी और बीजापुर व गोलकुंडा से मित्रता कर दक्कन में स्थायी शांति कायम रखी।\n3. विदेशी यात्री एवं शासक के अंतर्गत 'सर थॉमस रो (ब्रिटेन)' का ऐतिहासिक संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से था।\n4. इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":3,"explanation":"कथन 4 सत्य है (इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)   B. एत्मादुद्दौला का मकबरा (आगरा)\nC. किताब-ए-नवरस   D. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["एवं (लौह व )","किताब-ए-नवरस","एत्मादुद्दौला का मकबरा (आगरा)","हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार)"],"correct":0,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), हुमायूँ एवं शेरशाह सूरी (प्रशासन व आर्थिक सुधार) (1540-1545 ई.), किताब-ए-नवरस (1600 ई.), एत्मादुद्दौला का मकबरा (आगरा) (1626 ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **सत्य (सही)** है?\n1. मध्यकालीन स्थापत्य एवं निर्माता के अंतर्गत 'सिकंदर लोदी का मकबरा (1517)' का ऐतिहासिक संबंध 'शेरशाह सूरी' से था।\n2. 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।\n3. शिवाजी के अष्टप्रधान मंत्रिमंडल के सभी आठ पदों को 1674 में ही वंशानुगत कर दिया गया और पंडितराव को भी युद्धों का नेतृत्व अनिवार्य था।\n4. विदेशी यात्री एवं शासक के अंतर्गत 'इब्नबतूता (मोरक्को)' का ऐतिहासिक संबंध 'जहाँगीर (1615-1619 ई.)' से था।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":1,"explanation":"कथन 2 सत्य है (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।)। अन्य तीनों कथन तथ्यात्मक रूप से गलत हैं।"},
  {"q":"1191 ई. में तराइन के प्रथम युद्ध का क्या परिणाम रहा था?","options":["राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया","सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की"],"correct":2,"explanation":"1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया। परंतु अगले ही वर्ष 1192 ई. में तराइन के द्वितीय युद्ध में मुहम्मद गौरी विजयी रहा।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. बरार (इमादशाही) व बीदर (बरीदशाही)   2. तराइन का प्रथम युद्ध (1191 ई.)\n3. गुरु तेग बहादुर (नौवें गुरु)   4. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","options":["तराइन का प्रथम युद्ध (1191 ई.) → बरार (इमादशाही) व बीदर (बरीदशाही) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → गुरु तेग बहादुर (नौवें गुरु)","बरार (इमादशाही) व बीदर (बरीदशाही) → तराइन का प्रथम युद्ध (1191 ई.) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → गुरु तेग बहादुर (नौवें गुरु)","तराइन का प्रथम युद्ध (1191 ई.) → बरार (इमादशाही) व बीदर (बरीदशाही) → गुरु तेग बहादुर (नौवें गुरु) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","तराइन का प्रथम युद्ध (1191 ई.) → अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान → बरार (इमादशाही) व बीदर (बरीदशाही) → गुरु तेग बहादुर (नौवें गुरु)"],"correct":0,"explanation":"सही कालानुक्रम: तराइन का प्रथम युद्ध (1191 ई.) (1191 ई.), बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), गुरु तेग बहादुर (नौवें गुरु) (1675 ई.)"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।\nकथन-2: दक्कनी सल्तनत व राजवंश के अंतर्गत 'बरार (इमादशाही) व बीदर (बरीदशाही)' का ऐतिहासिक संबंध 'युसुफ आदिल शाह' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (दिल्ली सल्तनत में 'खालिसा' भूमि की आय सीधे शाही राजकोष में जाती थी और अलाउद्दीन खिलजी ने अनेक पुराने अनुदान ('इनाम', 'वक्फ', 'मिल्क') रद्द करके खालिसा भूमि का विस्तार किया।)। कथन-2 गलत है — 'बरार (इमादशाही) व बीदर (बरीदशाही)' का सही संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था — बरार सबसे पहले 1484-90 में अलग हुआ व 1574 में अहमदनगर में विलीन हुआ; बीदर सबसे अंत में अलग हुआ।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. केरल के कालड़ी में जन्मे शंकराचार्य ने चार मठों (ज्योतिर्मठ, शारदा, गोवर्धन, शृंगेरी) की स्थापना की।\n2. डोमिंगो पायस ने तुलुव वंश के कृष्णदेवराय के व्यक्तित्व व महानवमी उत्सव का सुंदर चित्रण किया।\n3. अलाउद्दीन खिलजी ने दक्षिण भारत के राज्यों (देवगिरि, वारंगल, होयसल) को प्रत्यक्ष रूप से दिल्ली सल्तनत के प्रांतों में मिला लिया।\n4. 1565 ई. के तालीकोटा (राक्षसी-तंगड़ी या बन्नीहट्टी) युद्ध में दक्कनी सल्तनतों (बीजापुर, अहमदनगर, गोलकुंडा, बीदर) के महासंघ ने रामराय को हराकर विजयनगर की शक्ति तोड़ दी।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: अलाउद्दीन ने व्यावहारिक नीति अपनाते हुए दक्षिण भारतीय राज्यों को केवल करद (वार्षिक नजराना देने वाले अधीनस्थ राज्य) बनाया, प्रत्यक्ष विलय नहीं किया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान   B. द्वैतवाद\nC. तराइन का प्रथम युद्ध (1191 ई.)   D. पुरंदर की संधि (1665 ई.)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["द्वैतवाद","(ई.)","पुरंदर की संधि (1665 ई.)","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान"],"correct":1,"explanation":"तराइन का प्रथम युद्ध (1191 ई.) (1191 ई.), द्वैतवाद (13वीं सदी ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), पुरंदर की संधि (1665 ई.) (1665 ई.)। अतः सर्वप्रथम तराइन का प्रथम युद्ध (1191 ई.)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'इब्नबतूता (मोरक्को)' का ऐतिहासिक संबंध 'जहाँगीर (1615-1619 ई.)' से था।\nकथन-2: मराठा संधियाँ एवं वर्ष के अंतर्गत 'पुरंदर की संधि (1665 ई.)' का ऐतिहासिक संबंध 'पेशवा को मराठा संघ का वास्तविक सर्वोच्च प्रमुख बना दिया गया' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'इब्नबतूता (मोरक्को)' का सही संबंध 'मुहम्मद बिन तुगलक (1333 ई.)' से था — मुहम्मद बिन तुगलक ने इब्नबतूता को दिल्ली का काजी नियुक्त किया और 1342 में चीन राजदूत भेजा। (2) 'पुरंदर की संधि (1665 ई.)' का सही संबंध 'शिवाजी एवं मिर्जा राजा जयसिंह (मुगल प्रतिनिधि)' से था — 1665 की पुरंदर संधि द्वारा शिवाजी ने अपने 35 में से 23 किले मुगलों को सौंपे और 12 छोटे किले रखे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया।\nकथन-2: शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) इल्तुतमिश ने अरबी शैली के शुद्ध सिक्के—चाँदी का 'टंका' (175 ग्रेन) और ताँबे का 'जीतल'—चलाए तथा 40 तुर्क अमीरों का 'तुर्कान-ए-चहलगानी' बनाया। (2) शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कुतुबुद्दीन ऐबक ने दिल्ली को अपनी स्थायी राजधानी बनाया और बगदाद के खलीफा से सुल्तान की औपचारिक उपाधि व सनद प्राप्त की।\nकथन-2: रामानुजाचार्य ने ब्रह्म को सगुण मानते हुए भक्ति (प्रपत्ति) को मोक्ष का सर्वश्रेष्ठ मार्ग बताया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":1,"explanation":"कथन-1 गलत है (ऐबक ने लाहौर से शासन किया और कभी सुल्तान की उपाधि व खलीफा से मान्यता नहीं ली; दिल्ली राजधानी और खलीफा मान्यता इल्तुतमिश ने प्राप्त की।)। कथन-2 सत्य है (रामानुजाचार्य ने ब्रह्म को सगुण मानते हुए भक्ति (प्रपत्ति) को मोक्ष का सर्वश्रेष्ठ मार्ग बताया।)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: विदेशी यात्री एवं शासक के अंतर्गत 'सर थॉमस रो (ब्रिटेन)' का ऐतिहासिक संबंध 'शाहजहाँ के अंतिम वर्ष व औरंगजेब काल (1656-68)' से था।\nकथन-2: दक्कनी सल्तनत व राजवंश के अंतर्गत 'अहमदनगर (निजामशाही, 1490)' का ऐतिहासिक संबंध 'फतुल्लाह इमाद-उल-मुल्क एवं अमीर अली बरीद' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":3,"explanation":"दोनों कथन असत्य हैं। (1) 'सर थॉमस रो (ब्रिटेन)' का सही संबंध 'जहाँगीर (1615-1619 ई.)' से था — थॉमस रो ने जहाँगीर से अजमेर व मांडू में भेंट कर ब्रिटिश ईस्ट इंडिया कंपनी को व्यापारिक छूट दिलाई। (2) 'अहमदनगर (निजामशाही, 1490)' का सही संबंध 'मलिक अहमद' से था — मलिक अहमद ने 1490 में अहमदनगर की स्थापना की; यहीं वजीर मलिक अंबर ने छापामार युद्ध व राजस्व सुधार किए।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार   B. अलाई दरवाजा (1311 ई.)\nC. सामूगढ़ का युद्ध (1658 ई.)   D. बीबी का मकबरा (औरंगाबाद)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["सामूगढ़ का युद्ध (1658 ई.)","अलाई दरवाजा (1311 ई.)","व सुधार","बीबी का मकबरा (औरंगाबाद)"],"correct":2,"explanation":"अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार (1296-1316 ई.), अलाई दरवाजा (1311 ई.) (1311 ई.), सामूगढ़ का युद्ध (1658 ई.) (1658 ई.), बीबी का मकबरा (औरंगाबाद) (1660 ई.)। अतः सर्वप्रथम अलाउद्दीन खिलजी: बाजार नियंत्रण व सैन्य-राजस्व सुधार।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n2. चंदावर का युद्ध (1194 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n3. करनाल का युद्ध (1739 ई.) : नादिर शाह ने मुगल सम्राट मुहम्मद शाह 'रंगीला' की सेना को हराया\n4. तक्कोलम का युद्ध (949 ई.) : राष्ट्रकूट कृष्ण तृतीय ने चोल शासक परांतक प्रथम के पुत्र राजादित्य को हराया","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":1,"explanation":"युग्म 2 गलत है: 'चंदावर का युद्ध (1194 ई.)' का सही संबंध 'मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया' से है (न कि 'पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया' से)। 1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: अकबर ने फतेहपुर सीकरी में 'मकतबखाना' (अनुवाद विभाग) स्थापित कराया जहाँ संस्कृत के प्रमुख महाकाव्यों व विज्ञान ग्रंथों का फारसी में अनुवाद हुआ।\nकथन-2: मुगलकालीन प्रमुख युद्ध के अंतर्गत 'चौसा का युद्ध (1539 ई.)' का ऐतिहासिक संबंध 'महाराणा प्रताप बनाम अकबर की सेना (मानसिंह व आसफ खाँ)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (अकबर ने फतेहपुर सीकरी में 'मकतबखाना' (अनुवाद विभाग) स्थापित कराया जहाँ संस्कृत के प्रमुख महाकाव्यों व विज्ञान ग्रंथों का फारसी में अनुवाद हुआ।)। कथन-2 गलत है — 'चौसा का युद्ध (1539 ई.)' का सही संबंध 'शेर खाँ (शेरशाह सूरी) द्वारा हुमायूँ की पराजय' से था — बक्सर के निकट चौसा में शेर खाँ ने हुमायूँ को हराया; निजाम भिश्ती ने हुमायूँ की जान बचाई।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. शाहजहाँ ने बलख-बदख्शां का मध्य एशिया अभियान किया, पुर्तगालियों को 1632 में हुगली से खदेड़ा और अहमदनगर (1633) को पूरी तरह मुगल साम्राज्य में मिलाया।\n2. 18 जून 1576 को अरावली की हल्दीघाटी में मेवाड़ के महाराणा प्रताप ने अदम्य शौर्य दिखाया।\n3. फिरोजशाह तुगलक ने अपने पूर्ववर्ती सुल्तानों की परंपरा के विपरीत सल्तनत में दास प्रथा को पूर्णतः अवैध घोषित कर समाप्त कर दिया।\n4. 1539 ई. में बक्सर के निकट चौसा के युद्ध में शेरशाह सूरी ने हुमायूँ को पराजित किया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: फिरोज तुगलक दासों का अत्यंत शौकीन था—उसके पास लगभग 1,80,000 दास थे जिनके प्रबंधन के लिए उसने 'दीवान-ए-बंदगान' विभाग बनाया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)   B. सिकंदर लोदी का मकबरा (1517)\nC. छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान   D. अब्दुर रज्जाक (फारस/समरकंद)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["ऐबक एवं (वंश)","अब्दुर रज्जाक (फारस/समरकंद)","छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान","सिकंदर लोदी का मकबरा (1517)"],"correct":0,"explanation":"कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), अब्दुर रज्जाक (फारस/समरकंद) (1443 ई.), सिकंदर लोदी का मकबरा (1517) (1517 ई.), छत्रपति शिवाजी महाराज: स्वराज, पुरंदर संधि व अष्टप्रधान (1674 ई.)। अतः सर्वप्रथम कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: कृष्णदेवराय का शासनकाल तेलुगु साहित्य का 'क्लासिकल युग' माना जाता है; उन्होंने पुर्तगालियों (गवर्नर अल्बुकर्क) से अरबी घोड़ों के व्यापार हेतु मैत्रीपूर्ण संबंध रखे।\nकथन-2: भक्ति मत एवं प्रवर्तक के अंतर्गत 'शुद्धाद्वैतवाद एवं पुष्टिमार्ग' का ऐतिहासिक संबंध 'बसवन्ना (बसव)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (कृष्णदेवराय का शासनकाल तेलुगु साहित्य का 'क्लासिकल युग' माना जाता है; उन्होंने पुर्तगालियों (गवर्नर अल्बुकर्क) से अरबी घोड़ों के व्यापार हेतु मैत्रीपूर्ण संबंध रखे।)। कथन-2 गलत है — 'शुद्धाद्वैतवाद एवं पुष्टिमार्ग' का सही संबंध 'वल्लभाचार्य' से था — वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)   B. अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान\nC. खानवा का युद्ध (1527 ई.)   D. फ्रांस्वा बर्नियर एवं टैवर्नियर\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["खानवा का युद्ध (1527 ई.)","फ्रांस्वा बर्नियर एवं टैवर्नियर","अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान","एवं (लौह व )"],"correct":3,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), खानवा का युद्ध (1527 ई.) (1527 ई.), अकबर: पानीपत द्वितीय, बैरम खाँ, हल्दीघाटी व विजय अभियान (1556-1605 ई.), फ्रांस्वा बर्नियर एवं टैवर्नियर (1658 ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)   B. फतवा-ए-जहाँदारी\nC. इकबालनामा-ए-जहाँगीरी   D. बरार (इमादशाही) व बीदर (बरीदशाही)\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["फतवा-ए-जहाँदारी","ऐबक एवं (वंश)","इकबालनामा-ए-जहाँगीरी","बरार (इमादशाही) व बीदर (बरीदशाही)"],"correct":1,"explanation":"कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश) (1211-1236 ई.), फतवा-ए-जहाँदारी (14वीं सदी ई.), बरार (इमादशाही) व बीदर (बरीदशाही) (1490 ई.), इकबालनामा-ए-जहाँगीरी (17वीं सदी ई.)। अतः सर्वप्रथम कुतुबुद्दीन ऐबक एवं इल्तुतमिश (मामलूक/गुलाम वंश)।"},
  {"q":"[PSC/CDS कथन परीक्षण] निम्नलिखित कथनों में से कौन-सा एक कथन ऐतिहासिक रूप से **असत्य (गलत)** है?\n1. गुरु अमरदास ने सती व पर्दा प्रथा का विरोध किया तथा सम्राट अकबर से गोइंदवाल में भेंट की।\n2. 1192 ई. का तराइन का द्वितीय युद्ध भारतीय इतिहास का युगांतकारी मोड़ था जिसने उत्तर भारत में चौहान शक्ति को समाप्त कर मुस्लिम तुर्क सत्ता स्थापित की।\n3. मुहम्मद बिन तुगलक ने अपनी सांकेतिक मुद्रा का निर्माण कठोर राजकीय टकसाल नियंत्रण के साथ केवल शुद्ध चाँदी से कराया था।\n4. निम्बार्काचार्य ने सनकादि संप्रदाय की स्थापना कर राधा-कृष्ण भक्ति को लोकप्रिय बनाया।","options":["कथन 1","कथन 2","कथन 3","कथन 4"],"correct":2,"explanation":"कथन 3 असत्य है। सुधार: मुहम्मद बिन तुगलक ने चाँदी की वैश्विक कमी के कारण ताँबे/काँसे की सांकेतिक मुद्रा चलाई, किंतु नकली सिक्कों की ढलाई न रोक पाने के कारण योजना विफल हुई।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।\nकथन-2: वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":2,"explanation":"दोनों कथन सत्य हैं। (1) 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया। (2) वल्लभाचार्य ने बिना संन्यास लिए गृहस्थ जीवन में कृष्ण के बाल रूप की भक्ति ('पुष्टिमार्ग') का उपदेश दिया।"},
  {"q":"[UPSC/PCS सूची सुमेलन — ऐतिहासिक युद्ध एवं परिणाम] सूची-I को सूची-II से सुमेलित कीजिए:\nA. चंदावर का युद्ध (1194 ई.)   |   1. राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया\nB. दाशराज्ञ युद्ध (परुष्णी नदी)   |   2. शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की\nC. हाइडेस्पीज का युद्ध (326 ई.पू.)   |   3. मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\nD. चौसा का युद्ध (1539 ई.)   |   4. सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की","options":["A-1, B-3, C-4, D-2","A-3, B-1, C-2, D-4","A-3, B-4, C-1, D-2","A-3, B-1, C-4, D-2"],"correct":3,"explanation":"सही सुमेलन: चंदावर का युद्ध (1194 ई.) (मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया), दाशराज्ञ युद्ध (परुष्णी नदी) (राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया), हाइडेस्पीज का युद्ध (326 ई.पू.) (सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की), चौसा का युद्ध (1539 ई.) (शेर खान (शेरशाह सूरी) ने हुमायूँ को पराजित कर 'शेरशाह' उपाधि धारण की)।"},
  {"q":"[UPSC Prelims पैटर्न — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों पर विचार कीजिए:\n1. तराइन का प्रथम युद्ध (1191 ई.) : पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया\n2. तालीकोटा का युद्ध (1565 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n3. चंदावर का युद्ध (1194 ई.) : अकबर-बैरम खाँ ने आदिल शाह के सेनापति हेमू (विक्रमादित्य) को हराया\nउपर्युक्त में से कितने युग्म सही सुमेलित हैं?","options":["केवल एक युग्म","केवल दो युग्म","सभी तीन युग्म","कोई भी युग्म नहीं"],"correct":0,"explanation":"युग्म 1 सही (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।) युग्म 2 गलत (सही: तालीकोटा का युद्ध (1565 ई.) — दक्कनी सल्तनतों के संघ ने विजयनगर के रामराय को पराजित किया)। युग्म 3 गलत (सही: चंदावर का युद्ध (1194 ई.) — मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया)।"},
  {"q":"[कालानुक्रम विश्लेषण] निम्नलिखित ऐतिहासिक घटनाओं पर विचार कीजिए:\nA. उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण   B. रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)\nC. गुरु अर्जुन देव (पाँचवें गुरु)   D. अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल\nइनमें से कौन-सी घटना **सबसे पहले (सर्वप्रथम)** घटित हुई?","options":["अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल","एवं (लौह व )","गुरु अर्जुन देव (पाँचवें गुरु)","उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण"],"correct":1,"explanation":"रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति) (1266-1287 ई.), अकबर की दहसाला व्यवस्था, मनसबदारी एवं सुलह-ए-कुल (1580 ई.), गुरु अर्जुन देव (पाँचवें गुरु) (1604 ई.), उत्तर-मुगल शासक, सैय्यद बंधु एवं नादिर शाह का आक्रमण (1739 ई.)। अतः सर्वप्रथम रजिया सुल्तान एवं गयासुद्दीन बलबन (लौह व रक्त नीति)।"},
  {"q":"[PSC/CDS युग्म विश्लेषण — ऐतिहासिक युद्ध एवं परिणाम] निम्नलिखित युग्मों में से कौन-सा एक सही सुमेलित **नहीं** है?\n1. नर्मदा तट का युद्ध (पुलकेशिन II बनाम हर्ष) : चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया\n2. चंदावर का युद्ध (1194 ई.) : मुहम्मद गौरी ने गहड़वाल शासक जयचंद्र को पराजित किया\n3. खानवा का युद्ध (1527 ई.) : बाबर ने मेवाड़ के राणा सांगा को हराकर 'गाजी' उपाधि ली\n4. तराइन का प्रथम युद्ध (1191 ई.) : राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया","options":["युग्म 1","युग्म 2","युग्म 3","युग्म 4"],"correct":3,"explanation":"युग्म 4 गलत है: 'तराइन का प्रथम युद्ध (1191 ई.)' का सही संबंध 'पृथ्वीराज चौहान तृतीय ने मुहम्मद गौरी को पराजित किया' से है (न कि 'राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया' से)। 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।"},
  {"q":"ऐतिहासिक संदर्भ में ''फवाजिल' (इक्तादार द्वारा केंद्र को भेजा जाने वाला अतिरिक्त राजस्व); 'खालिसा' (सीधे सुल्तान के नियंत्रण वाली भूमि); 'सोंधर/तकावी' (कृषि ऋण); 'शशगनी' (6 जीतल चाँदी का सिक्का)' (प्रमुख आर्थिक शब्द) का मुख्य संबंध किस विषय/व्यक्तित्व से है?","options":["चोल सम्राट राजराज प्रथम एवं राजेंद्र प्रथम","सल्तनत कालीन शब्दावली:  सोंधर, हक्क-ए-शर्ब व","चोल स्थानीय स्वशासन एवं उत्तरमेरूर अभिलेख","दिल्ली सल्तनत के केंद्रीय विभाग एवं प्रशासनिक शब्दावली"],"correct":1,"explanation":"'बरीद' (गुप्तचर) और 'मुन्हियान' (अलाउद्दीन के गुप्त सूचक) बाजार व प्रांतीय अधिकारियों पर सुल्तान की सीधी नजर रखते थे।"},
  {"q":"[UPSC/PCS कथन विश्लेषण] निम्नलिखित कथनों पर विचार कीजिए:\nकथन-1: 1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।\nकथन-2: भक्ति मत एवं प्रवर्तक के अंतर्गत 'अद्वैतवाद' का ऐतिहासिक संबंध 'रामानुजाचार्य (11वीं सदी, श्रीरंगम)' से था।\nउपर्युक्त में से कौन-सा/से कथन सही है/हैं?","options":["केवल 1","केवल 2","1 और 2 दोनों","न तो 1, न ही 2"],"correct":0,"explanation":"कथन-1 सत्य है (1191 ई. में तराइन के प्रथम युद्ध में पृथ्वीराज चौहान ने मुहम्मद गौरी को पराजित किया।)। कथन-2 गलत है — 'अद्वैतवाद' का सही संबंध 'आदि शंकराचार्य (8वीं-9वीं सदी)' से था — केरल के कालड़ी में जन्मे शंकराचार्य ने चार मठों (ज्योतिर्मठ, शारदा, गोवर्धन, शृंगेरी) की स्थापना की।"},
  {"q":"1194 ई. में 'चंदावर के युद्ध' में मुहम्मद गौरी ने कन्नौज के किस गहड़वाल शासक को हराया?","options":["चालुक्य नरेश पुलकेशिन द्वितीय ने हर्षवर्धन को हराया","सिकंदर ने पंजाब के शासक पोरस को पराजित कर मैत्री की","ने शासक जयचंद्र को पराजित किया","राजा सुदास (भरत जन) ने दस राजाओं के संघ को पराजित किया"],"correct":2,"explanation":"1194 ई. में चंदावर (इटावा-फिरोजाबाद के निकट) के युद्ध में गौरी ने जयचंद्र को हराया। जयचंद्र के दरबार में संस्कृत के प्रसिद्ध कवि श्रीहर्ष ('नैषधीयचरित') निवास करते थे।"},
  {"q":"[UPSC / CDS कालानुक्रम] निम्नलिखित ऐतिहासिक घटनाओं का प्राचीनतम से नवीनतम सही कालानुक्रम क्या है?\n1. करनाल का युद्ध (1739 ई.)   2. गुरु रामदास (चौथे गुरु)\n3. फर्नओ नूनिज (पुर्तगाल)   4. सुहरावर्दी सिलसिला (भारत)","options":["सुहरावर्दी सिलसिला (भारत) → फर्नओ नूनिज (पुर्तगाल) → करनाल का युद्ध (1739 ई.) → गुरु रामदास (चौथे गुरु)","फर्नओ नूनिज (पुर्तगाल) → सुहरावर्दी सिलसिला (भारत) → गुरु रामदास (चौथे गुरु) → करनाल का युद्ध (1739 ई.)","सुहरावर्दी सिलसिला (भारत) → गुरु रामदास (चौथे गुरु) → फर्नओ नूनिज (पुर्तगाल) → करनाल का युद्ध (1739 ई.)","सुहरावर्दी सिलसिला (भारत) → फर्नओ नूनिज (पुर्तगाल) → गुरु रामदास (चौथे गुरु) → करनाल का युद्ध (1739 ई.)"],"correct":3,"explanation":"सही कालानुक्रम: सुहरावर्दी सिलसिला (भारत) (13वीं सदी ई.), फर्नओ नूनिज (पुर्तगाल) (1535 ई.), गुरु रामदास (चौथे गुरु) (1577 ई.), करनाल का युद्ध (1739 ई.) (1739 ई.)"}
]);
